<?php $edit = !empty($x['user_id']); ?><h1><?= e($title) ?></h1><div class="panel narrow"><?php foreach ($errors as $m): ?><div class="alert error" role="alert"><?= e($m) ?></div><?php endforeach; ?>
<form method="post" action="<?= url('users/save') ?>" data-validate><?= csrf_field() ?><input type="hidden" name="id" value="<?= $edit ? (int)$x['user_id'] : '' ?>">
<label for="un">Username</label><input id="un" name="username" required pattern="[A-Za-z0-9._-]{3,50}" value="<?= e($x['username'] ?? '') ?>"><label for="ue">Email</label><input id="ue" type="email" name="email" required value="<?= e($x['email'] ?? '') ?>">
<?php if (($x['role'] ?? '') === 'customer'): ?><p class="muted">Customer accounts keep the customer role.</p><?php else: ?><label for="ur">Role</label><select id="ur" name="role" required><?php foreach (['staff', 'admin'] as $r): ?><option value="<?= $r ?>" <?= ($x['role'] ?? 'staff') === $r ? 'selected' : '' ?>><?= ucfirst($r) ?></option><?php endforeach; ?></select><?php endif; ?>
<label for="up"><?= $edit ? 'New password (leave blank to keep)' : 'Password' ?></label><input id="up" type="password" name="password" minlength="8" autocomplete="new-password" <?= $edit ? '' : 'required' ?>><button class="btn">Save account</button></form></div>
